import pandas as pd
import numpy as np
from io import BytesIO
import base64

# Obtener item actual
item = items[0]

# Buscar nombre del archivo
file_name = None

if 'file_name' in item['json']:
    file_name = item['json']['file_name']
elif 'fileName' in item['json']:
    file_name = item['json']['fileName']
elif 'message' in item['json'] and 'document' in item['json']['message']:
    if 'file_name' in item['json']['message']['document']:
        file_name = item['json']['message']['document']['file_name']

if not file_name and 'result' in item['json'] and 'file_path' in item['json']['result']:
    file_path = item['json']['result']['file_path']
    file_name = file_path.split('/')[-1]

if not file_name:
    file_name = 'archivo_desconocido'

# LEER DATOS BINARIOS
try:
    if 'data' in item['binary']:
        binary_data = item['binary']['data']

        if isinstance(binary_data, str):
            file_bytes = base64.b64decode(binary_data)
        elif hasattr(binary_data, 'data'):
            raw = binary_data.data
            if isinstance(raw, str):
                file_bytes = base64.b64decode(raw)
            else:
                file_bytes = bytes(list(raw))
        else:
            file_bytes = bytes(list(binary_data))
    else:
        return {'json': {'error': 'No se encontró data en binary'}}

except Exception as e:
    return {'json': {'error': f'Error accediendo binario: {str(e)}'}}

# DETECTAR Y PARSEAR ARCHIVO SEGÚN TIPO
df = None
file_type = None

try:
    # Obtener extensión
    extension = file_name.lower().split('.')[-1] if '.' in file_name else ''

    # 1. CSV
    if extension == 'csv':
        df = pd.read_csv(BytesIO(file_bytes))
        file_type = 'CSV'

    # 2. EXCEL
    elif extension in ['xlsx', 'xls', 'xlsm']:
        df = pd.read_excel(BytesIO(file_bytes))
        file_type = 'Excel'

    # 3. JSON
    elif extension == 'json':
        df = pd.read_json(BytesIO(file_bytes))
        file_type = 'JSON'

    # 4. TSV (Tab-separated)
    elif extension in ['tsv', 'tab']:
        df = pd.read_csv(BytesIO(file_bytes), sep='\t')
        file_type = 'TSV'

    # 5. TXT (intentar como CSV con varios separadores)
    elif extension == 'txt':
        # Intentar diferentes separadores
        for sep in [',', ';', '\t', '|']:
            try:
                df = pd.read_csv(BytesIO(file_bytes), sep=sep)
                if len(df.columns) > 1:  # Si detectó múltiples columnas
                    file_type = f'TXT ({sep})'
                    break
            except:
                continue

        if df is None:
            return {'json': {
                'error': 'No se pudo parsear el archivo TXT',
                'suggestion': 'Asegúrate que use separadores: , ; | o tabulaciones'
            }}

    # 6. PARQUET (si está disponible)
    elif extension == 'parquet':
        try:
            df = pd.read_parquet(BytesIO(file_bytes))
            file_type = 'Parquet'
        except ImportError:
            return {'json': {
                'error': 'Formato Parquet no soportado',
                'suggestion': 'Convierte el archivo a CSV o Excel'
            }}

    # 7. FORMATOS NO SOPORTADOS
    else:
        unsupported_formats = {
            'pdf': 'PDFs requieren procesamiento especial',
            'docx': 'Word requiere librerías adicionales',
            'doc': 'Word antiguo no soportado',
            'png': 'Imágenes no son archivos de datos tabulares',
            'jpg': 'Imágenes no son archivos de datos tabulares',
            'jpeg': 'Imágenes no son archivos de datos tabulares',
            'zip': 'Archivos comprimidos no soportados',
            'rar': 'Archivos comprimidos no soportados'
        }

        if extension in unsupported_formats:
            return {'json': {
                'error': f'Formato .{extension} no soportado',
                'reason': unsupported_formats[extension],
                'supported_formats': ['CSV', 'Excel (.xlsx, .xls)', 'JSON', 'TSV', 'TXT']
            }}

        # Intentar detectar automáticamente como CSV
        try:
            df = pd.read_csv(BytesIO(file_bytes))
            file_type = 'CSV (auto-detectado)'
        except:
            return {'json': {
                'error': f'Formato .{extension} no reconocido',
                'filename': file_name,
                'supported_formats': ['CSV', 'Excel (.xlsx, .xls)', 'JSON', 'TSV', 'TXT'],
                'suggestion': 'Convierte tu archivo a uno de los formatos soportados'
            }}

    # Verificar que se leyó correctamente
    if df is None or len(df) == 0:
        return {'json': {
            'error': 'No se pudieron extraer datos del archivo',
            'filename': file_name,
            'bytes_read': len(file_bytes)
        }}

except Exception as e:
    return {'json': {
        'error': f'Error parseando archivo: {str(e)}',
        'filename': file_name,
        'file_type': extension if 'extension' in locals() else 'desconocido'
    }}

# 1. INFORMACIÓN BÁSICA
basic_info = {
    'filename': file_name,
    'file_type': file_type,
    'rows': int(len(df)),
    'columns': int(len(df.columns)),
    'column_names': df.columns.tolist(),
    'memory_usage': f"{df.memory_usage(deep=True).sum() / 1024:.2f} KB"
}

# 2. TIPOS DE DATOS
data_types = {
    'numeric_columns': df.select_dtypes(include=[np.number]).columns.tolist(),
    'categorical_columns': df.select_dtypes(include=['object', 'category']).columns.tolist(),
    'datetime_columns': df.select_dtypes(include=['datetime64']).columns.tolist(),
    'dtypes': {k: str(v) for k, v in df.dtypes.to_dict().items()}
}

# 3. ESTADÍSTICAS DESCRIPTIVAS
numeric_df = df.select_dtypes(include=[np.number])
if not numeric_df.empty:
    stats_desc = {col: {k: float(v) if pd.notna(v) else None 
                       for k, v in stats.items()} 
                 for col, stats in numeric_df.describe().to_dict().items()}
else:
    stats_desc = {}

# 4. MISSING VALUES
missing_values = {
    'total_missing': int(df.isnull().sum().sum()),
    'missing_by_column': {k: int(v) for k, v in df.isnull().sum().to_dict().items()},
    'missing_percentage': {k: float(round(v, 2)) for k, v in (df.isnull().sum() / len(df) * 100).to_dict().items()}
}

# 5. DETECCIÓN DE OUTLIERS
outliers_info = {}
for col in numeric_df.columns:
    Q1 = numeric_df[col].quantile(0.25)
    Q3 = numeric_df[col].quantile(0.75)
    IQR = Q3 - Q1
    lower_bound = Q1 - 1.5 * IQR
    upper_bound = Q3 + 1.5 * IQR
    outliers = numeric_df[(numeric_df[col] < lower_bound) | (numeric_df[col] > upper_bound)][col]

    outliers_info[col] = {
        'count': int(len(outliers)),
        'percentage': float(round(len(outliers) / len(df) * 100, 2)),
        'lower_bound': float(lower_bound) if not pd.isna(lower_bound) else None,
        'upper_bound': float(upper_bound) if not pd.isna(upper_bound) else None
    }

# 6. CORRELACIONES
if len(numeric_df.columns) > 1:
    correlation_matrix = {k: {k2: float(v2) if not pd.isna(v2) else None for k2, v2 in v.items()} 
                         for k, v in numeric_df.corr().to_dict().items()}

    corr_df = numeric_df.corr()
    np.fill_diagonal(corr_df.values, 0)
    strong_correlations = []

    for i in range(len(corr_df.columns)):
        for j in range(i+1, len(corr_df.columns)):
            corr_val = corr_df.iloc[i, j]
            if not pd.isna(corr_val) and abs(corr_val) > 0.5:
                strong_correlations.append({
                    'var1': str(corr_df.columns[i]),
                    'var2': str(corr_df.columns[j]),
                    'correlation': float(round(corr_val, 3))
                })
else:
    correlation_matrix = {}
    strong_correlations = []

# 7. VALORES ÚNICOS
unique_values = {}
for col in data_types['categorical_columns'][:5]:
    unique_count = int(df[col].nunique())
    if unique_count <= 20:
        value_counts = df[col].value_counts().head(10)
        unique_values[col] = {
            'count': unique_count,
            'values': {str(k): int(v) for k, v in value_counts.to_dict().items()}
        }
    else:
        unique_values[col] = {
            'count': unique_count,
            'note': 'Demasiadas categorías para listar'
        }

# 8. MUESTRA DE DATOS
data_sample = []
for _, row in df.head(5).iterrows():
    row_dict = {}
    for col in df.columns:
        val = row[col]
        if pd.isna(val):
            row_dict[col] = None
        elif isinstance(val, (np.int64, np.int32)):
            row_dict[col] = int(val)
        elif isinstance(val, (np.float64, np.float32)):
            row_dict[col] = float(val)
        else:
            row_dict[col] = str(val)
    data_sample.append(row_dict)

# 9. RECOMENDACIONES ML
recommendations = []
potential_targets = [col for col in df.columns if any(keyword in col.lower() 
                    for keyword in ['target', 'label', 'class', 'y', 'price', 'sales', 'revenue', 'churn'])]

if potential_targets:
    target_col = potential_targets[0]
    unique_count = int(df[target_col].nunique())

    if df[target_col].dtype in [np.int64, np.int32] and unique_count < 10:
        recommendations.append({
            'type': 'Clasificación',
            'target_column': target_col,
            'num_classes': unique_count,
            'models': ['Logistic Regression', 'Random Forest', 'XGBoost', 'SVM'],
            'reason': f'Variable objetivo categórica con {unique_count} clases'
        })
    elif df[target_col].dtype in [np.float64, np.int64]:
        recommendations.append({
            'type': 'Regresión',
            'target_column': target_col,
            'models': ['Linear Regression', 'Random Forest', 'XGBoost', 'Ridge'],
            'reason': 'Variable objetivo numérica continua'
        })
else:
    recommendations.append({
        'type': 'Análisis Exploratorio / No Supervisado',
        'models': ['K-Means', 'PCA', 'DBSCAN', 't-SNE'],
        'reason': 'No se detectó variable objetivo'
    })

# Preprocesamiento
preprocessing = []
if missing_values['total_missing'] > 0:
    preprocessing.append('⚠️ Imputar o eliminar valores faltantes')
if any(info['count'] > 0 for info in outliers_info.values()):
    preprocessing.append('⚠️ Tratar outliers (IQR, Z-score)')
if len(data_types['categorical_columns']) > 0:
    preprocessing.append('📝 Encodear variables categóricas')
if len(numeric_df.columns) > 0:
    preprocessing.append('📏 Escalar features numéricas')
if len(df) < 100:
    preprocessing.append('⚠️ Dataset pequeño - considerar cross-validation')

# RESULTADO
result = {
    'basic_info': basic_info,
    'data_types': data_types,
    'statistics': stats_desc,
    'missing_values': missing_values,
    'outliers': outliers_info,
    'correlations': {
        'matrix': correlation_matrix,
        'strong_correlations': strong_correlations
    },
    'unique_values': unique_values,
    'data_sample': data_sample,
    'ml_recommendations': recommendations,
    'preprocessing_steps': preprocessing
}

return {'json': result}

