const files = items.map(i => i.json);
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const userId = $('Telegram Trigger').first().json.message.from.id;

// Ordenar: primero activos, luego por timestamp
files.sort((a, b) => {
  if (a.activo && !b.activo) return -1;
  if (!a.activo && b.activo) return 1;
  return new Date(b.timestamp) - new Date(a.timestamp);
});

// Construir mensaje
let message = "📂 TUS ARCHIVOS ANALIZADOS\n";
message += "━━━━━━━━━━━━━━━━━━\n\n";

files.forEach((file, index) => {
  const statusIcon = file.activo ? "✅" : "⚪";
  const statusText = file.activo ? "🟢 Activo" : "🔴 Apagado";

  message += `${statusIcon} ${index + 1}. ${file.filename} (ID: ${file.Id})\n`;
  message += `   ${statusText}\n\n`;
});

message += "━━━━━━━━━━━━━━━━━━\n";
message += "💡 Para activar un archivo usa:\n";
message += "   /activar [número id]\n";
message += "   Ejemplo: /activar 2\n\n";
message += "💡 Para desactivar todos:\n";
message += "   /desactivar\n\n";
message += "⚠️ Solo 1 archivo puede estar activo";

return [{
  json: {
    telegram_message: message,
    files_count: files.length,
    chatId: chatId,
    userId: userId
  }
}];

const text = $input.first().json.message.text;

// Buscar el patrón /activar seguido de un número (en cualquier parte del mensaje)
const match = text.match(/\/activar\s+(\d+)/);

const userId = $input.first().json.message.from.id;
const chatId = $input.first().json.message.chat.id;

if (!match) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: "❌ Formato incorrecto.\n\n✅ Usa: /activar [número]\nEjemplo: /activar 2"
    }
  }];
}

return [{
  json: {
    userId: userId,
    chatId: chatId,
    fileNumber: parseInt(match[1]),
    error: false
  }
}];

